from typing import List


def frogGame(blocks: List[int]) -> int:
    # 青蛙只能跳到相邻且不低于当前高度的方块（Codility 原题规则）
    n = len(blocks)
    left = list(range(n))   # left[i]：从 i 出发向左能到的最远下标
    for i in range(1, n):
        if blocks[i - 1] >= blocks[i]:
            left[i] = left[i - 1]
    right = list(range(n))  # right[i]：从 i 出发向右能到的最远下标
    for i in range(n - 2, -1, -1):
        if blocks[i + 1] >= blocks[i]:
            right[i] = right[i + 1]
    # 距离按 Codility 原题定义 K - J + 1
    return max(right[i] - left[i] + 1 for i in range(n))


if __name__ == "__main__":
    assert frogGame([2, 6, 8, 5]) == 3
    assert frogGame([1, 5, 5, 2, 6]) == 4
    assert frogGame([1, 1]) == 2
    assert frogGame([1, 2, 3, 4, 5, 8]) == 6       # 题面样例 2
    print(frogGame([9, 2, 5, 3, 0]))                # 题面样例 1 期望 2，见题解说明
